import React, { useState, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";
import axios from "axios";

const GAMYAM_COLORS = {
  darkBg: '#000000',
  darkCard: '#1a1a1a',
  orange: '#ff7c26',
  textLight: '#ffffff',
  textMuted: '#b2b2b3',
  border: '#333333',
};

export default function JobDetails() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [job, setJob] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    fetchJobDetails();
  }, [id]);

  const fetchJobDetails = async () => {
    try {
      const response = await axios.get("http://localhost:5000/api/jobs");
      const foundJob = response.data.find((j) => j._id === id);

      if (foundJob) {
        setJob(foundJob);
      } else {
        setError("Job not found");
      }
      setLoading(false);
    } catch (err) {
      console.error("Error fetching job details:", err);
      setError("Failed to load job details");
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div style={styles.loadingContainer}>
        <div style={styles.loader}></div>
        <p style={{ color: GAMYAM_COLORS.orange, marginTop: "20px" }}>Loading job details...</p>
      </div>
    );
  }

  if (error || !job) {
    return (
      <div style={styles.errorContainer}>
        <h2 style={{ color: GAMYAM_COLORS.orange }}>⚠️ {error || "Job not found"}</h2>
        <button style={styles.applyBtn} onClick={() => navigate("/")}>
          ← Back to Job Listings
        </button>
      </div>
    );
  }

  return (
    <div style={styles.page}>
      <div style={styles.backButton} onClick={() => navigate("/")}>
        <span style={styles.backArrow}>←</span>
        <span style={styles.backText}>See all jobs</span>
      </div>

      <div style={styles.container}>
        {/* Left Sidebar */}
        <div style={styles.sidebar}>
          <div style={styles.sidebarCard}>
            <div style={styles.iconBox}>
              <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                <polyline points="20 6 9 17 4 12"></polyline>
              </svg>
            </div>
            <h3 style={styles.sidebarTitle}>Apply now</h3>
            <p style={styles.sidebarDesc}>
              Apply for this job and hear back from the hiring manager in under 48 hours!
            </p>
            <button style={styles.applyBtn} onClick={() => navigate(`/apply/${id}`)}>
              Apply now
            </button>
          </div>

          <div style={styles.sidebarCard}>
            <h3 style={styles.sidebarTitle}>About the company</h3>
            <p style={styles.sidebarDesc}>
              Gamyam is a tech company that delivers on-demand, high-quality AI engineering talent to help businesses build and scale faster.
            </p>
            <button style={styles.viewCompanyBtn}>
              View company
            </button>
          </div>
        </div>

        {/* Main Content */}
        <div style={styles.mainContent}>
          <div style={styles.jobHeader}>
            <h1 style={styles.jobTitle}>{job.title}</h1>

            <div style={styles.jobMeta}>
              <div style={styles.metaGroup}>
                <span style={styles.metaLabel}>Location</span>
                <span style={styles.metaValue}>{job.location}</span>
              </div>
              <div style={styles.metaGroup}>
                <span style={styles.metaLabel}>Type</span>
                <span style={styles.metaValue}>{job.jobType}</span>
              </div>
              <div style={styles.metaGroup}>
                <span style={styles.metaLabel}>Experience</span>
                <span style={styles.metaValue}>{job.experience}</span>
              </div>
              <div style={styles.metaGroup}>
                <span style={styles.metaLabel}></span>
                <span style={styles.metaValue}>{job.ctc}</span>
              </div>
            </div>
          </div>

          <div style={styles.section}>
            <div style={styles.sectionHeader}>
              <h2 style={styles.sectionTitle}>Job Description</h2>
              <span style={styles.postedDate}>Posted on: {job.deadline || "Recently"}</span>
            </div>

            <div style={styles.jobDetails}>
              <p style={styles.detailRow}><strong>Location:</strong> {job.location}</p>
              <p style={styles.detailRow}><strong>CTC Range:</strong> {job.ctc}</p>
              <p style={styles.detailRow}><strong>Employment Type:</strong> {job.jobType}</p>
              {job.department && job.department !== "NA" && (
                <p style={styles.detailRow}><strong>Department:</strong> {job.department}</p>
              )}
              {job.role && job.role !== "NA" && (
                <p style={styles.detailRow}><strong>Industry Type:</strong> {job.role}</p>
              )}
            </div>
          </div>

          <div style={styles.section}>
            <h2 style={styles.sectionTitle}>Job Overview</h2>
            <p style={styles.sectionText}>{job.description}</p>
          </div>

          {job.responsibilities && job.responsibilities !== "NA" && (
            <div style={styles.section}>
              <h2 style={styles.sectionTitle}>Key Responsibilities</h2>
              <div style={styles.sectionText}>
                {job.responsibilities.split('\n').map((resp, index) => (
                  <div key={index} style={styles.bulletPoint}>
                    <span style={styles.bullet}>•</span>
                    <span>{resp.trim()}</span>
                  </div>
                ))}
              </div>
            </div>
          )}

          {job.benefits && job.benefits !== "NA" && (
            <div style={styles.section}>
              <h2 style={styles.sectionTitle}>What We Offer</h2>
              <div style={styles.sectionText}>
                {job.benefits.split('\n').map((benefit, index) => (
                  <div key={index} style={styles.bulletPoint}>
                    <span style={styles.bullet}>•</span>
                    <span>{benefit.trim()}</span>
                  </div>
                ))}
              </div>
            </div>
          )}

          {job.qualifications && job.qualifications !== "NA" && (
            <div style={styles.section}>
              <h2 style={styles.sectionTitle}>Education</h2>
              <div style={styles.sectionText}>
                {job.qualifications.split('\n').map((qual, index) => (
                  <div key={index} style={styles.bulletPoint}>
                    <span style={styles.bullet}>•</span>
                    <span>{qual.trim()}</span>
                  </div>
                ))}
              </div>
            </div>
          )}

          <div style={styles.section}>
            <h2 style={styles.sectionTitle}>Preferred Key Skills</h2>
            <div style={styles.skillsList}>
              {job.skillset.split(",").map((skill, index) => (
                <span key={index} style={styles.skillBadge}>
                  {skill.trim()}
                  {index < job.skillset.split(",").length - 1 && " · "}
                </span>
              ))}
            </div>
          </div>

          <button style={styles.applyBtnBottom} onClick={() => navigate(`/apply/${id}`)}>
            Apply now
          </button>
        </div>
      </div>
    </div>
  );
}

const styles = {
  page: {
    minHeight: "100vh",
    background: GAMYAM_COLORS.darkBg,
